body {
  color: #2c2016;
  background-color: #f7f1e3;
}

h1 {
  color: #5a3e2b;
}

h2 {
  color: #5a3e2b;
}

a {
  color: #e08a2e;
}

footer {
  background-color: #efe6d4;
}

table {
  background-color: white;
}

.hinweis {
  color: #b8860b;
  font-weight: bold;
}

